    73  /**
    74   *      Decode a TACACS+ 'arg_N' fields.
    75   */
    76  static int tacacs_decode_args(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_attr_t const *parent,
    77                                uint8_t arg_cnt, uint8_t const *arg_list, uint8_t const **data, uint8_t const *end)
    78  {
    79          uint8_t i;
    80          uint8_t const *p = *data;
    81          fr_pair_t *vp;
    82
    83          /*
    84           *      No one? Just get out!
    85           */
    86          if (!arg_cnt) return 0;
    87
    88          if ((p + arg_cnt) > end) {
    89                  fr_strerror_printf("Argument count %u overflows the remaining data in the packet", arg_cnt);
    90                  return -1;
    91          }
    92
    93          /*
    94           *      Then, do the dirty job...
    95           */
    96          for (i = 0; i < arg_cnt; i++) {
    97                  uint8_t const *value, *name_end, *arg_end;
    98                  fr_dict_attr_t const *da;
    99                  uint8_t buffer[256];
   100
   101                  if (arg_list[i] < 2) goto next; /* skip malformed */
   102
   103                  if (p + arg_list[i] > end) {
   104                          fr_strerror_printf("'%s' argument %u length %u overflows the remaining data in the packet",
   105                                             parent->name, i, arg_list[i]);
   106                          return -1;
   107                  }
   108
   109                  memcpy(buffer, p, arg_list[i]);
   110                  buffer[arg_list[i]] = '\0';
   111
   112                  arg_end = buffer + arg_list[i];
   113
   114                  for (value = buffer, name_end = NULL; value < arg_end; value++) {
   115                          /*
   116                           *      RFC 8907 Section 3.7 says control
   117                           *      characters MUST be excluded.
   118                           */
   119                          if (*value < ' ') goto next;
   120
   121                          if ((*value == '=') || (*value == '*')) {
   122                                  name_end = value;
   123                                  buffer[value - buffer] = '\0';
   124                                  value++;
   125                                  break;
   126                          }
   127                  }
   128
   129                  /*
   130                   *      Skip fields which aren't in "name=value" or "name*value" format.
   131                   */
   132                  if (!name_end) goto next;
   133
   134                  da = fr_dict_attr_by_name(NULL, fr_dict_root(dict_tacacs), (char *) buffer);
   135                  if (!da) {
   136                  raw:
   137                          /*
   138                           *      Dupe the whole thing so that we have:
   139                           *
   140                           *      Argument-List += "name=value"
   141                           */
   142                          da = parent;
   143                          value = p;
   144                          arg_end = p + arg_list[i];
   145                  }
   146
   147                  vp = fr_pair_afrom_da(ctx, da);
   148                  if (!vp) {
   149                          fr_strerror_const("Out of Memory");
   150                          return -1;
   151
   152                  }
   153
   154                  /*
   155                   *      Parse the string, and try to convert it to the
   156                   *      underlying data type.  If it can't be
   157                   *      converted as a data type, just convert it as
   158                   *      Argument-List.
   159                   *
   160                   *      And if that fails, just ignore it completely.
   161                   */
   162                  if (fr_pair_value_from_str(vp, (char const *) value, arg_end - value, 0, true) < 0) {
   163                          talloc_free(vp);
   164                          if (da != parent) goto raw;
   165
   166                          goto next;
   167                  }
   168
   169                  fr_dcursor_append(cursor, vp);
   170
   171          next:
   172                  p += arg_list[i];
   173                  *data  = p;
   174          }
   175
   176          return 0;
   177  }
