   311                          return -1;
   312                  }
   313
   314                  length = ntohl(pkt->hdr.length);
   315
   316                  /*
   317                   *      We need that to decrypt the body content.
   318                   */
   319                  decrypted = talloc_memdup(ctx, buffer, buffer_len);
   320                  if (!decrypted) {
   321                          fr_strerror_const("Out of Memory");
   322                          return -1;
   323                  }
   324
   325                  pkt = (fr_tacacs_packet_t const *) decrypted;
   326                  end = decrypted + buffer_len;
   327
   328                  if (fr_tacacs_body_xor(pkt, decrypted + sizeof(pkt->hdr), length, secret, secret_len) < 0) {
   329                  fail:
   330                          talloc_free(decrypted);
   331                          return -1;
   332                  }
   333
   334                  FR_PROTO_HEX_DUMP(decrypted, buffer_len, "fr_tacacs_packet_t (unencrypted)");
   335          }
